head.script:
// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
    var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
    var r = d(id); if (r) return r;
    var s = dd(P + id); r = d(s); if (r) return r;
    var g = s.indexOf('G_');
    if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
    return d(s.replace(P, ''));
};
scwin.checkVal1 = function() {
    return scwin.__getDom('windowContainer1_nameLayer_'+$p.id+'windowContainer1_subWindow0') == null;
}
scwin.checkVal2 = function() {
    return scwin.__getDom('windowContainer1_nameLayer_'+$p.id+'windowContainer1_subWindow1') == null;
}
scwin.checkVal3 = function() {
    return scwin.__getDom('windowContainer1_nameLayer_'+$p.id+'windowContainer1_subWindow2') == null;
}
scwin.onpageload = function() {
    windowContainer1.createWindow("naver", "", "http://www.naver.com", "네이버", "1", "", "");
    windowContainer1.createWindow("daum", "", "http://www.daum.net", "다음", "2", "", "");
    windowContainer1.createWindow("ppomppu", "", "http://www.ppomppu.co.kr/index.php", "뽐뿌", "3", "", "");
};
